class Solution {
public:
    int countGoodStrings(int low, int high, int zero, int one) {
        const int MOD = 1000000007;
        int M = max(zero, one);
        vector<int> buf(M, 0);
        buf[0] = 1; // dp[0] = 1: one way to build the empty string
        long long ans = 0;
        for (int i = 1; i <= high; i++) {
            long long val = 0;
            if (i >= zero) val += buf[(i - zero) % M];
            if (i >= one)  val += buf[(i - one)  % M];
            val %= MOD;
            buf[i % M] = (int)val; // write after both reads are done
            if (i >= low) ans = (ans + val) % MOD;
        }
        return (int)ans;
    }
};
